import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math

model_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Naive GEMM kernel: out[B, out_features] = inp[B, in_features] * weight[in_features, out_features] + bias[out_features]
__global__ void gemm_kernel(
    const float* __restrict__ inp,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    const int B,
    const int IN,
    const int OUT
) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < B && col < OUT) {
        float val = 0.0f;
        for(int i = 0; i < IN; i++){
            val += inp[row * IN + i] * weight[i * OUT + col];
        }
        val += bias[col];
        out[row * OUT + col] = val;
    }
}

// GEMM wrapper
torch::Tensor gemm_cuda(torch::Tensor inp, torch::Tensor weight, torch::Tensor bias) {
    int B = inp.size(0);
    int IN = inp.size(1);
    int OUT = weight.size(1);

    auto out = torch::empty({B, OUT}, torch::dtype(inp.dtype()).device(inp.device()));

    dim3 block(16, 16);
    dim3 grid((B + block.x - 1) / block.x, (OUT + block.y - 1) / block.y);

    gemm_kernel<<<grid, block>>>(
        inp.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        B, IN, OUT
    );

    return out;
}

// Elementwise subtract: out = inp - subParam, shapes: inp[B, OUT], subParam[OUT]
__global__ void subtract_kernel(
    const float* __restrict__ inp,
    const float* __restrict__ subParam,
    float* __restrict__ out,
    const int B,
    const int OUT
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = B * OUT;
    if (idx < size) {
        int col = idx % OUT;
        out[idx] = inp[idx] - subParam[col];
    }
}

// Sub wrapper
torch::Tensor subtract_cuda(torch::Tensor inp, torch::Tensor subParam) {
    int B = inp.size(0);
    int OUT = inp.size(1);

    auto out = torch::empty_like(inp);

    int size = B * OUT;
    int blockSize = 256;
    int gridSize = (size + blockSize - 1) / blockSize;

    subtract_kernel<<<gridSize, blockSize>>>(
        inp.data_ptr<float>(),
        subParam.data_ptr<float>(),
        out.data_ptr<float>(),
        B, OUT
    );

    return out;
}

// Global average pool over dim=1 (out_features), producing shape [B, 1]
__global__ void global_avg_pool_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    const int B,
    const int OUT
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B) {
        float sum_val = 0.0f;
        for (int j = 0; j < OUT; j++) {
            sum_val += inp[idx * OUT + j];
        }
        sum_val /= (float)OUT;
        out[idx] = sum_val;  // [B, 1] flattened as [B]
    }
}

// GlobalAvgPool wrapper
torch::Tensor global_avg_pool_cuda(torch::Tensor inp) {
    int B = inp.size(0);
    int OUT = inp.size(1);

    auto out = torch::empty({B, 1}, torch::dtype(inp.dtype()).device(inp.device()));

    int blockSize = 256;
    int gridSize = (B + blockSize - 1) / blockSize;

    global_avg_pool_kernel<<<gridSize, blockSize>>>(
        inp.data_ptr<float>(),
        out.data_ptr<float>(),
        B, OUT
    );

    return out;
}

// LogSumExp over dim=1 for shape [B, 1] -> effectively if shape is [B, 1], the result is the same value
// but let's do a generic approach for safety
__global__ void logsumexp_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    const int B,
    const int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B) {
        float max_val = inp[idx * W];
        // find max
        for (int j = 1; j < W; j++) {
            float v = inp[idx * W + j];
            if (v > max_val) max_val = v;
        }
        // sum exp
        float sum_val = 0.0f;
        for (int j = 0; j < W; j++) {
            sum_val += expf(inp[idx * W + j] - max_val);
        }
        float log_val = max_val + logf(sum_val);
        out[idx] = log_val; // store as single value
    }
}

// LogSumExp wrapper
torch::Tensor logsumexp_cuda(torch::Tensor inp) {
    // assume logsumexp along dim=1
    int B = inp.size(0);
    int W = inp.size(1);  // might be 1 in typical usage here
    auto out = torch::empty({B, 1}, torch::dtype(inp.dtype()).device(inp.device()));

    int blockSize = 256;
    int gridSize = (B + blockSize - 1) / blockSize;

    logsumexp_kernel<<<gridSize, blockSize>>>(
        inp.data_ptr<float>(),
        out.data_ptr<float>(),
        B, W
    );

    return out;
}

// GELU: out = 0.5 * x * (1 + erf(x / sqrt(2)))
__global__ void gelu_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    const int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = inp[idx];
        float c = 0.7071067811865475f; // 1 / sqrt(2)
        out[idx] = 0.5f * val * (1.0f + erff(val * c));
    }
}

// GELU wrapper
torch::Tensor gelu_cuda(torch::Tensor inp) {
    int size = inp.numel();
    auto out = torch::empty_like(inp);

    int blockSize = 256;
    int gridSize = (size + blockSize - 1) / blockSize;

    gelu_kernel<<<gridSize, blockSize>>>(
        inp.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}

// ResidualAdd kernel: broadcast shape [B, 1] to match original_x[B, in_features]
// out[B, in_features] = x[B,1] + original_x[B,in_features]
__global__ void residual_add_kernel(
    const float* __restrict__ small,
    const float* __restrict__ orig,
    float* __restrict__ out,
    const int B,
    const int IN
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = B * IN;
    if (idx < size) {
        int row = idx / IN;
        out[idx] = small[row] + orig[idx];
    }
}

// ResidualAdd wrapper
torch::Tensor residual_add_cuda(torch::Tensor small, torch::Tensor orig) {
    // small: [B, 1], orig: [B, in_features]
    int B = orig.size(0);
    int IN = orig.size(1);

    auto out = torch::empty_like(orig);

    int size = B * IN;
    int blockSize = 256;
    int gridSize = (size + blockSize - 1) / blockSize;

    residual_add_kernel<<<gridSize, blockSize>>>(
        small.data_ptr<float>(),
        orig.data_ptr<float>(),
        out.data_ptr<float>(),
        B, IN
    );

    return out;
}

TORCH_LIBRARY(my_model_ops, m) {
    m.def("gemm_cuda", gemm_cuda);
    m.def("subtract_cuda", subtract_cuda);
    m.def("global_avg_pool_cuda", global_avg_pool_cuda);
    m.def("logsumexp_cuda", logsumexp_cuda);
    m.def("gelu_cuda", gelu_cuda);
    m.def("residual_add_cuda", residual_add_cuda);
}
""";

model_ops_cpp_decl = r"""
torch::Tensor gemm_cuda(torch::Tensor inp, torch::Tensor weight, torch::Tensor bias);
torch::Tensor subtract_cuda(torch::Tensor inp, torch::Tensor subParam);
torch::Tensor global_avg_pool_cuda(torch::Tensor inp);
torch::Tensor logsumexp_cuda(torch::Tensor inp);
torch::Tensor gelu_cuda(torch::Tensor inp);
torch::Tensor residual_add_cuda(torch::Tensor small, torch::Tensor orig);
"""

model_ops = load_inline(
    name="model_ops",
    cpp_sources=model_ops_cpp_decl,
    cuda_sources=model_ops_source,
    functions=[
        "gemm_cuda",
        "subtract_cuda",
        "global_avg_pool_cuda",
        "logsumexp_cuda",
        "gelu_cuda",
        "residual_add_cuda",
    ],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    """
    Optimized model that performs the same operations via custom CUDA kernels:
    GMP -> Subtract -> GlobalAvgPool -> LogSumExp -> GELU -> ResidualAdd.
    """
    def __init__(self, in_features, out_features, bias=True):
        super(ModelNew, self).__init__()
        # We'll mimic nn.Linear with custom params
        self.in_features = in_features
        self.out_features = out_features
        self.weight = nn.Parameter(torch.randn(in_features, out_features))
        if bias:
            self.bias = nn.Parameter(torch.randn(out_features))
        else:
            self.bias = None
        self.subtract = nn.Parameter(torch.randn(out_features))

    def forward(self, x):
        # Save original
        original_x = x.clone()

        # GEMM
        if self.bias is not None:
            x = model_ops.gemm_cuda(x, self.weight.t(), self.bias)
        else:
            bias_zeros = torch.zeros(self.out_features, device=x.device, dtype=x.dtype)
            x = model_ops.gemm_cuda(x, self.weight.t(), bias_zeros)

        # Subtract
        x = model_ops.subtract_cuda(x, self.subtract)

        # GlobalAvgPool
        x = model_ops.global_avg_pool_cuda(x)

        # LogSumExp
        x = model_ops.logsumexp_cuda(x)

        # GELU
        x = model_ops.gelu_cuda(x)

        # ResidualAdd (broadcast x[B,1] with original_x[B,in_features])
        x = model_ops.residual_add_cuda(x.view(-1), original_x)

        return x
